import math

def check_perpendicular(n):
    diagonals = []
    for a in range(n):
        for b in range(a + 2, n):
            if a == 0 and b == n - 1:
                continue
            diagonals.append((a, b))

    count = 0
    for i in range(len(diagonals)):
        for j in range(i + 1, len(diagonals)):
            a, b = diagonals[i]
            c, d = diagonals[j]

            # Dot product formula: 
            # cos(2*pi*(b-d)/n) - cos(2*pi*(b-c)/n) - cos(2*pi*(a-d)/n) + cos(2*pi*(a-c)/n)
            val = (math.cos(2 * math.pi * (b - d) / n) - 
                   math.cos(2 * math.pi * (b - c) / n) - 
                   math.cos(2 * math.pi * (a - d) / n) + 
                   math.cos(2 * math.pi * (a - c) / n))
            if abs(val) < 1e-9:
                count += 1
    return count

